codeExample.bad:
// Auto-logs the user out after 60 seconds with no warning and no way to extend
setTimeout(() => {
  logUserOut();
}, 60000);

codeExample.good:
// Warns the user 20 seconds before the limit and lets them extend it,
// repeatably, before logging out
let warningTimer = setTimeout(showExtendWarning, 40000);
let logoutTimer = setTimeout(logUserOut, 60000);

function showExtendWarning() {
  const extend = confirmDialog('Your session is about to expire. Extend it?');
  if (extend) {
    clearTimeout(logoutTimer);
    warningTimer = setTimeout(showExtendWarning, 40000);
    logoutTimer = setTimeout(logUserOut, 60000);
  }
}
